<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class CustomerController extends Controller
{
    private function stations(Request $request){return $request->user()->role==='Super Admin'?DB::table('stations')->where('active',true)->pluck('id'):$request->user()->stations()->where('stations.active',true)->pluck('stations.id');}
    public function index(Request $request){abort_unless($request->user()->hasPermission('customers.view'),403);$ids=$this->stations($request);$stations=DB::table('stations')->whereIn('id',$ids)->get();$ledgerBalances=DB::table('customer_ledgers')->select('customer_id',DB::raw('SUM(debit - credit) as balance'))->groupBy('customer_id');$customers=DB::table('customers')->leftJoinSub($ledgerBalances,'ledger_balances',fn($join)=>$join->on('customers.id','=','ledger_balances.customer_id'))->whereIn('customers.station_id',$ids)->where('customers.active',true)->select('customers.*',DB::raw('COALESCE(ledger_balances.balance, customers.opening_balance) as outstanding'))->orderBy('customers.name')->get();return view('customers.index',compact('stations','customers'));}
    public function store(Request $request){abort_unless($request->user()->hasPermission('customers.manage'),403);$data=$request->validate(['station_id'=>'required|integer','name'=>'required|string|max:255','mobile'=>'nullable|string|max:30','address'=>'nullable|string|max:255','vehicle_number'=>'nullable|string|max:30','gst_number'=>'nullable|string|max:30','credit_limit'=>'required|numeric|min:0','opening_balance'=>'required|numeric|min:0']);abort_unless($this->stations($request)->contains((int)$data['station_id']),403);$id=DB::table('customers')->insertGetId([...$data,'active'=>true,'created_at'=>now(),'updated_at'=>now()]);if((float)$data['opening_balance']>0)DB::table('customer_ledgers')->insert(['customer_id'=>$id,'entry_date'=>now()->toDateString(),'reference'=>'Opening balance','debit'=>$data['opening_balance'],'credit'=>'0.00','created_by'=>$request->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('audit_logs')->insert(['user_id'=>$request->user()->id,'station_id'=>$data['station_id'],'action'=>'customer_created','entity_type'=>'customer','entity_id'=>$id,'details'=>null,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Customer created.');}
    public function edit(Request $request,int $customer){abort_unless($request->user()->hasPermission('customers.manage'),403);$record=DB::table('customers')->where('id',$customer)->whereIn('station_id',$this->stations($request))->first();abort_unless($record,404);$stations=DB::table('stations')->whereIn('id',$this->stations($request))->orderBy('name')->get();return view('customers.edit',compact('record','stations'));}
    public function update(Request $request,int $customer){abort_unless($request->user()->hasPermission('customers.manage'),403);$record=DB::table('customers')->where('id',$customer)->whereIn('station_id',$this->stations($request))->first();abort_unless($record,404);$data=$request->validate(['name'=>'required|string|max:255','mobile'=>'nullable|string|max:30','address'=>'nullable|string|max:255','vehicle_number'=>'nullable|string|max:30','gst_number'=>'nullable|string|max:30','credit_limit'=>'required|numeric|min:0']);DB::table('customers')->where('id',$customer)->update([...$data,'updated_at'=>now()]);DB::table('audit_logs')->insert(['user_id'=>$request->user()->id,'station_id'=>$record->station_id,'action'=>'customer_updated','entity_type'=>'customer','entity_id'=>$customer,'details'=>json_encode($data),'created_at'=>now(),'updated_at'=>now()]);return redirect()->route('customers.index')->with('success','Customer details updated.');}
    public function deactivate(Request $request,int $customer){abort_unless($request->user()->hasPermission('customers.manage'),403);$record=DB::table('customers')->where('id',$customer)->whereIn('station_id',$this->stations($request))->where('active',true)->first();abort_unless($record,404);DB::table('customers')->where('id',$customer)->update(['active'=>false,'updated_at'=>now()]);DB::table('audit_logs')->insert(['user_id'=>$request->user()->id,'station_id'=>$record->station_id,'action'=>'customer_deactivated','entity_type'=>'customer','entity_id'=>$customer,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Customer deactivated. Historical invoices and ledger entries were retained.');}
    public function receipt(Request $request,int $customer){abort_unless($request->user()->hasPermission('customers.manage'),403);$data=$request->validate(['amount'=>'required|numeric|gt:0','payment_date'=>'required|date','mode'=>'required|in:Cash,UPI,Bank,Card','reference'=>'nullable|string|max:100']);$ids=$this->stations($request);DB::transaction(function()use($request,$customer,$data,$ids){$record=DB::table('customers')->where('id',$customer)->whereIn('station_id',$ids)->lockForUpdate()->first();abort_unless($record,404);$balance=DB::table('customer_ledgers')->where('customer_id',$customer)->sum(DB::raw('debit-credit'));if((float)$data['amount']>(float)$balance)throw \Illuminate\Validation\ValidationException::withMessages(['amount'=>'Receipt cannot exceed the outstanding balance.']);DB::table('payments')->insert(['station_id'=>$record->station_id,'customer_id'=>$customer,'created_by'=>$request->user()->id,'payment_date'=>$data['payment_date'],'mode'=>$data['mode'],'amount'=>$data['amount'],'reference'=>$data['reference']??'Customer receipt','created_at'=>now(),'updated_at'=>now()]);DB::table('customer_ledgers')->insert(['customer_id'=>$customer,'entry_date'=>$data['payment_date'],'reference'=>$data['reference']??'Customer receipt','debit'=>'0.00','credit'=>$data['amount'],'created_by'=>$request->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('audit_logs')->insert(['user_id'=>$request->user()->id,'station_id'=>$record->station_id,'action'=>'customer_receipt_recorded','entity_type'=>'customer','entity_id'=>$customer,'details'=>json_encode(['amount'=>$data['amount']]),'created_at'=>now(),'updated_at'=>now()]);});return back()->with('success','Customer receipt recorded.');}
}
